        path = entry['path']
        # Remove query string if present
        if '?' in path:
            path = path.split('?', 1)[0]
        if path in path_counts:
            path_counts[path] += 1
        else:
            path_counts[path] = 1

    # Sort by count (descending) then by path (ascending)
